<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Service\Visibility\PlatformIdentityVisibilityService;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class PlatformIdentityRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly PlatformIdentityVisibilityService $visibility,
        private readonly PlatformIdentityReadGateway $reader
    ) {
    }

    public function allowRetrieve(?PlatformIdentityRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Platform identity");
        $span = $this->startSpan("Check allow of retrieve usecase for Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?PlatformIdentityRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Platform identity");
        $span = $this->startSpan("Check hidden fields usecase for Platform identity");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): PlatformIdentityRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Platform identity");
        $span = $this->startSpan("Run retrieve usecase for Platform identity");
        try {
            $ref = new PlatformIdentityRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Platform identity');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new PlatformIdentityRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
